import os
import tomllib
from typing import Any


class EnvCfgError(Exception):
    """Raised when environment variables cannot be coerced or are unmapped."""
    pass


def _coerce(value: str, target_type: type) -> Any:
    """Coerce a string to the given type, raising EnvCfgError on failure."""
    if target_type is int:
        try:
            return int(value)
        except ValueError:
            raise EnvCfgError(f"expected int, got \"{value}\"")
    if target_type is float:
        try:
            return float(value)
        except ValueError:
            raise EnvCfgError(f"expected float, got \"{value}\"")
    if target_type is bool:
        lower = value.lower()
        if lower in ("true", "1", "yes"):
            return True
        if lower in ("false", "0", "no"):
            return False
        raise EnvCfgError(f"expected bool, got \"{value}\"")
    if target_type is str:
        return value
    raise EnvCfgError(f"unsupported type {target_type.__name__}")


def _deep_merge(base: dict, override: dict) -> dict:
    """Recursively merge override into base, returning a new dict."""
    result = base.copy()
    for key, val in override.items():
        if key in result and isinstance(result[key], dict) and isinstance(val, dict):
            result[key] = _deep_merge(result[key], val)
        else:
            result[key] = val
    return result


