import os
import pytest
from envcfg import load, EnvCfgError


def test_defaults_only():
    cfg = load({"a": 1, "b": 2})
    assert cfg == {"a": 1, "b": 2}


def test_toml_overrides_defaults():
    # Create a temporary TOML file
    toml_path = "/tmp/test_envcfg.toml"
    with open(toml_path, "w") as f:
        f.write('a = 10\nb = 20\nc = 30')
    try:
        cfg = load({"a": 1, "b": 2}, toml_path=toml_path)
        assert cfg == {"a": 10, "b": 20, "c": 30}
    finally:
        os.remove(toml_path)


def test_missing_toml_file_is_skipped():
    cfg = load({"a": 1}, toml_path="/nonexistent/path.toml")
    assert cfg == {"a": 1}


def test_nested_defaults():
    cfg = load({"server": {"port": 8080, "host": "localhost"}})
    assert cfg == {"server": {"port": 8080, "host": "localhost"}}


def test_toml_nested_overrides_defaults():
    toml_path = "/tmp/test_envcfg_nested.toml"
    with open(toml_path, "w") as f:
        f.write('''
[server]
port = 9000
host = "0.0.0.0"

[database]
port = 5432
''')
    try:
        cfg = load(
            {"server": {"port": 8080, "host": "localhost"}, "database": {"port": 3306}},
            toml_path=toml_path,
        )
        assert cfg == {
            "server": {"port": 9000, "host": "0.0.0.0"},
            "database": {"port": 5432},
        }
    finally:
        os.remove(toml_path)


def test_env_overrides_defaults():
    os.environ["APP__A"] = "100"
    os.environ["APP__B"] = "200"
    try:
        cfg = load({"a": 1, "b": 2}, prefix="APP")
        assert cfg == {"a": 100, "b": 200}
    finally:
        del os.environ["APP__A"]
        del os.environ["APP__B"]


